const D = { energy: .55, scale: 1, glaze: .45, craze: .5, density: .5, alpha: .85, hue: 36, speed: 1, x: .5, y: .5, style: 'varnish', act: 'gallery', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// RESCUE NOTE: v1 was effectively a NO-OP — lum .084 over a .088 bed, motion
// .0084. The cause was structural, not cosmetic: every single effect was
// MULTIPLY (the glaze, the foxing) or OVERLAY (the weave, the craquelure), and
// both are mathematical no-ops on a near-black frame. Multiplying dark navy by
// amber gives dark navy; overlaying anything onto ~0 gives ~0. So the pass
// contributed nothing at all. The fix is to add the parts of a real varnished
// panel that EMIT rather than absorb: plate tone, varnish bloom, foxing lit by
// the lamp, and crack lips that ignite additively where the lamp rakes them.
// It still reads as a pass OVER content — the multiply chain is all still here.

const cl=(v,a,b)=>v<a?a:v>b?b:v, md=(a,n)=>((a%n)+n)%n, TAU=Math.PI*2;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
const hsb2rgb=(h,s,b)=>{ h=(((h%360)+360)%360)/60; s=cl(s,0,100)/100; b=cl(b,0,100)/100;
  const c=b*s, x=c*(1-Math.abs((h%2)-1)), m=b-c; let r,g,l;
  if(h<1){r=c;g=x;l=0;} else if(h<2){r=x;g=c;l=0;} else if(h<3){r=0;g=c;l=x;}
  else if(h<4){r=0;g=x;l=c;} else if(h<5){r=x;g=0;l=c;} else {r=c;g=0;l=x;}
  return [((r+m)*255)|0,((g+m)*255)|0,((l+m)*255)|0]; };
const rgba=(c,a)=>'rgba('+c[0]+','+c[1]+','+c[2]+','+a.toFixed(4)+')';
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width, Hh=height, u=Math.min(W,Hh);
const sty=P.style, act=P.act;
const gz=cl(P.glaze,0,1.3), cz=cl(P.craze,0,1.3), al=cl(P.alpha,0,1);
const sc=cl(P.scale,.5,2.2), dens=cl(P.density,0,1), spd=cl(P.speed,.2,4);
const en=cl(P.energy,0,1)*(.55+.55*K.intensity);
const T=K.t*spd, H=md(P.hue,360);
const ax=cl(P.x,0,1), ay=cl(P.y,0,1);

S.bass=(S.bass||0)*.86+(A.bass||0)*.14;
const kick=Math.min(1,K.pulse*.38+S.bass*.5);

// ---- the panel: what kind of surface the light is falling on ----
const foxed=(sty==='foxed'), wet=(sty==='wet'), xray=(sty==='xray');
let glH,glS,glB, crazeE=cz, weave=!foxed&&!wet, gloss=1.0, foxE;
if(foxed){ glH=md(H+52,360); glS=22; glB=64; crazeE=cz*.55; gloss=.5; foxE=1; }
else if(wet){ glH=md(H+4,360); glS=30; glB=90; crazeE=cz*.12; gloss=2.0; foxE=0; }
else if(xray){ glH=md(H+164,360); glS=24; glB=72; crazeE=cz*1.7; gloss=.6; foxE=.2; }
else { glH=H; glS=62; glB=62; gloss=1.0; foxE=.34; }   // every aged panel has some foxing

let glazeE=gz, sheenE=1;
if(act==='raking'){ sheenE=2.3; glazeE*=.7; gloss*=1.3; }
else if(act==='age'){ const q=.5+.5*Math.sin(T*.019); glazeE*=.55+1.1*q; crazeE*=.5+1.0*q; foxE*=.5+1.2*q; }

const dc=drawingContext, oldOp=dc.globalCompositeOperation;

// ---- 1. what fresh varnish / a bleach bath does to the colour under it ----
if(wet){
  dc.globalCompositeOperation='saturation'; dc.globalAlpha=cl(.18+.26*en,0,.55)*al;
  dc.fillStyle='rgb(255,0,0)'; dc.fillRect(0,0,W,Hh);
  dc.globalAlpha=1; dc.globalCompositeOperation=oldOp;
} else if(xray){
  dc.globalCompositeOperation='saturation'; dc.globalAlpha=cl(.44+.30*(1-en),0,.86)*al;
  dc.fillStyle='rgb(128,128,128)'; dc.fillRect(0,0,W,Hh);
  dc.globalAlpha=1; dc.globalCompositeOperation=oldOp;
}

// ---- 2. the glaze: an uneven, drifting film of aged varnish (absorbs) ----
if(glazeE>.01){
  const gc=hsb2rgb(glH,glS,glB);
  dc.globalCompositeOperation='multiply';
  const lg=dc.createLinearGradient(0,0,W*.35,Hh);
  lg.addColorStop(0,rgba(gc,cl(.30*glazeE*al,0,.85)));
  lg.addColorStop(.55,rgba(gc,cl(.19*glazeE*al,0,.85)));
  lg.addColorStop(1,rgba(gc,cl(.28*glazeE*al,0,.85)));
  dc.fillStyle=lg; dc.fillRect(0,0,W,Hh);
  dc.globalCompositeOperation=oldOp;
}

// ---- 3. PLATE TONE + varnish bloom: the parts that EMIT ----
// A lit varnished panel scatters light back out of the film — it does not only
// darken what is under it. This is what gives the pass presence on a dark frame,
// and the drift is a second motion floor under the lamp.
{
  const tc=hsb2rgb(md(glH+6,360),Math.min(100,glS*.7),100);
  dc.globalCompositeOperation='lighter';
  const tx=(.5+.18*Math.sin(T*.017)+.07*Math.sin(T*.041))*W;
  const ty=(.5+.14*Math.cos(T*.013)+.06*Math.sin(T*.037))*Hh;
  const tg=dc.createRadialGradient(tx,ty,0,tx,ty,u*(1.05+.15*Math.sin(T*.023)));
  const ta=cl((.050+.075*glazeE)*(.45+.7*en)*al,0,.17);
  tg.addColorStop(0,rgba(tc,ta));
  tg.addColorStop(.6,rgba(tc,ta*.5));
  tg.addColorStop(1,rgba(tc,ta*.14));
  dc.fillStyle=tg; dc.fillRect(0,0,W,Hh);
  // varnish bloom: the cloudy patches where the film went off, catching light
  const NBL=4+Math.round(dens*4);
  for(let i=0;i<NBL;i++){
    const bx=(fr(i*13)+.10*Math.sin(T*.029+i*1.7)+.05*Math.sin(T*.071+i))*W;
    const by=(fr(i*13+1)+.08*Math.cos(T*.023+i*2.3)+.04*Math.sin(T*.061+i))*Hh;
    const rr=u*(.20+fr(i*13+2)*.34)*sc;
    const bc=hsb2rgb(md(glH+(fr(i*13+3)-.5)*30,360), glS*(.4+fr(i*13+4)*.5), 100);
    const rg=dc.createRadialGradient(bx,by,0,bx,by,rr);
    rg.addColorStop(0,rgba(bc,cl(.055*glazeE*(.4+.8*en)*al,0,.13)));
    rg.addColorStop(1,rgba(bc,0));
    dc.fillStyle=rg; dc.fillRect(bx-rr,by-rr,rr*2,rr*2);
  }
  dc.globalCompositeOperation=oldOp;
}

// ---- 4. foxing: brown mould bloom + a tide-line where the water stopped ----
if(foxE>.01){
  const NFX=Math.round((10+dens*30)*foxE);
  // the stain absorbs...
  dc.globalCompositeOperation='multiply';
  for(let i=0;i<NFX;i++){
    const bx=(fr(i*17)+.012*Math.sin(T*.11+i))*W, by=(fr(i*17+1)+.010*Math.cos(T*.09+i*1.3))*Hh;
    const gr2=.5+.5*Math.sin(T*.037+fr(i*17+4)*TAU);
    const rr=u*(.008+fr(i*17+2)*.030)*(.6+.7*gr2)*sc;
    const bc=hsb2rgb(md(H-8+fr(i*17+3)*26,360),58,54);
    const rg=dc.createRadialGradient(bx,by,0,bx,by,rr);
    rg.addColorStop(0,rgba(bc,cl(.34*glazeE*al,0,.7)));
    rg.addColorStop(.6,rgba(bc,cl(.16*glazeE*al,0,.5)));
    rg.addColorStop(1,rgba(bc,0));
    dc.fillStyle=rg; dc.fillRect(bx-rr,by-rr,rr*2,rr*2);
  }
  // ...but the raised rim of each spot still catches the room
  dc.globalCompositeOperation='lighter';
  for(let i=0;i<NFX;i++){
    const bx=(fr(i*17)+.012*Math.sin(T*.11+i))*W, by=(fr(i*17+1)+.010*Math.cos(T*.09+i*1.3))*Hh;
    const gr2=.5+.5*Math.sin(T*.037+fr(i*17+4)*TAU);
    const rr=u*(.008+fr(i*17+2)*.030)*(.6+.7*gr2)*sc;
    const bc=hsb2rgb(md(H+14+fr(i*17+3)*20,360),30,100);
    const rg=dc.createRadialGradient(bx,by,rr*.5,bx,by,rr);
    rg.addColorStop(0,rgba(bc,0));
    rg.addColorStop(.75,rgba(bc,cl(.10*foxE*(.4+.8*en)*al,0,.16)));
    rg.addColorStop(1,rgba(bc,0));
    dc.fillStyle=rg; dc.fillRect(bx-rr,by-rr,rr*2,rr*2);
  }
  if(foxed){
    const tc=hsb2rgb(md(H+4,360),52,52);
    dc.globalCompositeOperation='multiply';
    dc.strokeStyle=rgba(tc,cl(.26*glazeE*al,0,.6)); dc.lineWidth=Math.max(2,u*.006);
    dc.beginPath();
    for(let x=0;x<=W;x+=W/24){
      const y=(ay*.72+.14)*Hh + Math.sin(x*.004+T*.031)*u*.045 + Math.sin(x*.011-T*.017)*u*.02;
      if(x===0) dc.moveTo(x,y); else dc.lineTo(x,y); }
    dc.stroke();
  }
  dc.globalCompositeOperation=oldOp;
}

// ---- 5. the surface: canvas weave + craquelure, baked once as a relief plate --
// S.surf is a 128-grey OVERLAY plate (works over real content); S.lip holds the
// lit crack lips ALONE on transparent, for the additive pass that is the only
// thing that survives on a dark frame.
const skey=W+'x'+Hh+'|'+sty+'|'+P.seed+'|'+Math.round(sc*10);
if(!S.surf||S.sk!==skey){
  const g=(S.surf&&S.surf.width===W&&S.surf.height===Hh)?S.surf:createGraphics(W,Hh);
  const lp=(S.lip&&S.lip.width===W&&S.lip.height===Hh)?S.lip:createGraphics(W,Hh);
  g.colorMode(HSB,360,100,100,100); g.noStroke(); g.background(0,0,50.2);
  lp.colorMode(HSB,360,100,100,100); lp.clear(); lp.noStroke();
  const pit=Math.max(3,u*.0042*sc);
  if(weave){
    g.strokeWeight(1);
    for(let y=0;y<Hh;y+=pit){ g.stroke(0,0,58,58); g.line(0,y,W,y); }
    for(let x=0;x<W;x+=pit){ g.stroke(0,0,43,52); g.line(x,0,x,Hh); }
    g.noStroke();
    for(let i=0;i<1400;i++){ const x=fr(i*23)*W, y=fr(i*23+1)*Hh;
      g.fill(0,0,fr(i*23+2)>.5?62:39,26); g.circle(x,y,.9+fr(i*23+3)*2.2); }
    lp.strokeWeight(1);                                  // the weave tooth catches light too
    for(let y=0;y<Hh;y+=pit){ lp.stroke(0,0,100,13); lp.line(0,y,W,y); }
    lp.noStroke();
  } else {
    g.strokeWeight(1);
    for(let x=0;x<W;x+=pit*6){ g.stroke(0,0,54,30); g.line(x,0,x,Hh); }
    for(let y=0;y<Hh;y+=pit*1.3){ g.stroke(0,0,52,22); g.line(0,y,W,y); }
    g.noStroke();
    for(let i=0;i<1000;i++){ const x=fr(i*29)*W, y=fr(i*29+1)*Hh;
      g.fill(0,0,fr(i*29+2)>.5?60:41,22); g.circle(x,y,.8+fr(i*29+3)*2.4); }
  }
  // craquelure: a jittered mesh of age-cracks, each with a raised lit lip
  const cs=Math.max(11,u*.055*sc);
  const cols=Math.ceil(W/cs)+2, rows=Math.ceil(Hh/cs)+2;
  const NX=(i,j)=>(i-1)*cs+(fr(i*97+j*13)-.5)*cs*.66;
  const NY=(i,j)=>(j-1)*cs+(fr(i*31+j*57+7)-.5)*cs*.66;
  const seg=(x0,y0,x1,y1,jit,dark,lite,wd)=>{
    const dx=x1-x0, dy=y1-y0, L=Math.sqrt(dx*dx+dy*dy)+1e-5, px2=-dy/L, py2=dx/L;
    const N=4, xs=[], ys=[];
    for(let k=0;k<=N;k++){ const t=k/N, w=(k===0||k===N)?0:(fr(x0*.7+y0*.31+k*3.7)-.5)*jit;
      xs.push(x0+dx*t+px2*w); ys.push(y0+dy*t+py2*w); }
    g.noFill(); g.strokeWeight(wd*1.5); g.stroke(0,0,dark,88);
    g.beginShape(); for(let k=0;k<=N;k++) g.vertex(xs[k],ys[k]); g.endShape();
    g.strokeWeight(wd*.85); g.stroke(0,0,lite,66);
    g.beginShape(); for(let k=0;k<=N;k++) g.vertex(xs[k]+px2*wd*1.5,ys[k]+py2*wd*1.5); g.endShape();
    lp.noFill(); lp.strokeWeight(wd*.85); lp.stroke(0,0,100,74);
    lp.beginShape(); for(let k=0;k<=N;k++) lp.vertex(xs[k]+px2*wd*1.5,ys[k]+py2*wd*1.5); lp.endShape();
  };
  const dk=xray?18:26, lt=xray?96:78, wd=Math.max(1,u*.0013);
  for(let j=0;j<rows;j++) for(let i=0;i<cols;i++){
    const x0=NX(i,j), y0=NY(i,j);
    if(fr(i*7+j*11+3)>.13) seg(x0,y0,NX(i+1,j),NY(i+1,j),cs*.30,dk,lt,wd);
    if(fr(i*7+j*11+5)>.13) seg(x0,y0,NX(i,j+1),NY(i,j+1),cs*.30,dk,lt,wd);
  }
  g.noStroke(); lp.noStroke(); S.surf=g; S.lip=lp; S.sk=skey; }

if(crazeE>.01){
