// ---- 6. the gallery lamp: a gloss reflection wandering over the varnish ----
const lx=ax+.34*Math.sin(T*.055)+.16*Math.sin(T*.118+1.3)+.07*Math.sin(T*.0193);
const ly=ay+.26*Math.cos(T*.047)+.13*Math.sin(T*.101+.7);
const mw=cl(Math.round(W/2),120,760), mh=cl(Math.round(mw*Hh/Math.max(1,W)),80,520);
if(!S.mk||S.mw!==mw||S.mh!==mh){ if(S.mk&&S.mk.remove)S.mk.remove(); S.mk=createGraphics(mw,mh); S.mw=mw; S.mh=mh; }
// the raised crack lips ignite where the lamp rakes across them
