  mc.drawImage(S.lip.canvas||S.lip.elt,0,0,mw,mh);
  mc.globalCompositeOperation='destination-in';
  const rg=mc.createRadialGradient(lx*mw,ly*mh,0,lx*mw,ly*mh,mw*(.30+.10*Math.sin(T*.053)));
  rg.addColorStop(0,'rgba(255,255,255,1)'); rg.addColorStop(.5,'rgba(255,255,255,0.55)'); rg.addColorStop(1,'rgba(255,255,255,0)');
  mc.fillStyle=rg; mc.fillRect(0,0,mw,mh);
  mc.globalCompositeOperation='source-over';
  dc.globalCompositeOperation='lighter';
  dc.globalAlpha=cl(crazeE*.42*(.45+.7*en)*gloss*al,0,.55);
  image(S.mk,0,0,W,Hh);
