const rg2=dc.createRadialGradient(lx*W,ly*Hh,0,lx*W,ly*Hh,gr3);
rg2.addColorStop(0,rgba(gc2,cl(.175*gloss*(.45+.8*en)*(1+.25*kick*en)*al,0,.40)));
rg2.addColorStop(.4,rgba(gc2,cl(.070*gloss*al,0,.26)));
rg2.addColorStop(1,rgba(gc2,0));
dc.fillStyle=rg2; dc.fillRect(lx*W-gr3,ly*Hh-gr3,gr3*2,gr3*2);

// ---- 7. raking sheen: the slow pass of a conservator's lamp across the panel --
const sa=.28+.12*Math.sin(T*.027), ux=Math.cos(sa), uy=Math.sin(sa);
const L2=Math.abs(W*ux)+Math.abs(Hh*uy)+1;
const cpos=(((T*.034*sheenE)%1)+1)%1*L2, bw=u*.19*sc;
const ox=W/2-(L2/2-cpos)*ux, oy=Hh/2-(L2/2-cpos)*uy;
const lg2=dc.createLinearGradient(ox-bw*ux,oy-bw*uy,ox+bw*ux,oy+bw*uy);
lg2.addColorStop(0,'rgba(255,255,255,0)');
lg2.addColorStop(.5,rgba(gc2,cl((.045+.075*gloss*en)*al,0,.20)));
lg2.addColorStop(1,'rgba(255,255,255,0)');
dc.fillStyle=lg2; dc.fillRect(0,0,W,Hh);
dc.globalCompositeOperation=oldOp;

